const imageExtensions = {
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/webp": "webp",
  "image/avif": "avif",
  "image/jxl": "jxl",
  "image/heic": "heic",
};
function planImage(item, folderId) {
  if (!Object.hasOwn(imageExtensions, item?.mimeType)) return null;
  if (
    typeof folderId !== "string" ||
    folderId === "YOUR_OUTPUT_FOLDER_ID" ||
    !/^[A-Za-z0-9_-]{2,512}$/.test(folderId)
  ) {
    throw new Error("Configure a Google Drive output folder");
  }
  if (!Array.isArray(item.parents) || !item.parents.length || item.parents.includes(folderId)) {
    throw new Error("Use a separate destination folder for optimised copies");
  }
  const id = item.fileId ?? item.id;
  if (typeof id !== "string" || !/^[A-Za-z0-9_-]+$/.test(id) || !item.name?.trim()) {
    throw new Error("Drive event did not identify the image");
  }
  const outputMime = item.mimeType === "image/heic" ? "image/jpeg" : item.mimeType;
  const base = item.name.replace(/\.(?:jpe?g|png|webp|avif|jxl|heic)$/i, "");
  const extension =
    outputMime === "image/jpeg" && /\.jpeg$/i.test(item.name)
      ? "jpeg"
      : imageExtensions[outputMime];
  return {
    id,
    inputMime: item.mimeType,
    outputMime,
    name: base + "-optimised." + extension,
    folderId,
  };
}
export default function prepare({ events, folderId }) {
  const files = events
    .filter((item) => item.eventType === "file_created")
    .map((item) => planImage(item, folderId))
    .filter(Boolean);
  return { files };
}

