export default function check({ file, image }) {
  if (
    file?.fileId !== image.id ||
    file?.mimeType !== image.inputMime ||
    typeof file?.transitUrl !== "string" ||
    !/^https:\/\/[^\s/?#]+\//i.test(file.transitUrl)
  ) {
    throw new Error("Drive did not return the requested image download");
  }
  return { url: file.transitUrl };
}

