function checkShrink({ url, id, info, outputMime }) {
  const match =
    typeof url === "string" && /^https:\/\/api\.tinify\.com\/output\/([A-Za-z0-9_-]+)$/.exec(url);
  if (!match || (id !== undefined && id !== match[1])) {
    throw new Error("Tinify returned an invalid output URL");
  }
  if (info?.type !== outputMime || !Number.isSafeInteger(info.size) || info.size < 1) {
    throw new Error("Tinify returned invalid output metadata");
  }
  return { imageId: match[1], size: info.size };
}
export default function verify({ url, id, info, image }) {
  const result = checkShrink({ url, id, info, outputMime: image.outputMime });
  if (result.size > 2097152) throw new Error("Optimised image exceeds the 2 MiB upload limit");
  return result;
}

