export default function check({ id, resultId, result, size, image }) {
  if (
    resultId !== id ||
    result?.mimeType !== image.outputMime ||
    result?.sizeBytes !== size ||
    typeof result?.downloadUrl !== "string" ||
    !/^https:\/\/[^\s/?#]+\//i.test(result.downloadUrl)
  ) {
    throw new Error("TinyPNG did not return the expected image reference");
  }
  return { url: result.downloadUrl };
}

